    {
      "beat": "What it does and does not show",
      "narration": "The authors read this as supporting a microbial contribution to fat mass in these mice, but that rests on the primary donor pair alone, and the pooled and pair-fed results in the record do not support it.",
      "on_screen": "Closing card: 'Donor pair 1 only | pooled CI includes no effect | pair-fed difference not significant | germ-free mice, fat mass only'",
      "claim_refs": ["CL06"]
    }
  ]
}
